+    assert.equal((await response.json()).error.code, 'INVALID_IDEMPOTENCY_KEY');
+  }
+  const result = await (await fetch(`${base}/api/orders?checkoutId=${input.checkoutId}`)).json();
+  assert.equal(result.total, 0);
+}));
